import{_ as o,o as l,c as s,a as e}from"./chunks/framework.BPFk9-tb.js";const m=JSON.parse('{"title":"写作课作业-027","description":"","frontmatter":{"date":"2020-08-15T20:22:20","title":"写作课作业-027","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/027.md","filePath":"posts/homework/027.md"}'),a={name:"posts/homework/027.md"};function n(r,t,p,c,u,d){return l(),s("div",null,[...t[0]||(t[0]=[e("blockquote",null,[e("p",null,"《定投改变命运》有很多精彩类比，再请找出来一两个类比，给自己带来什么启示？思考能不能用在其他地方？")],-1),e("blockquote",null,[e("p",null,"柏拉图在两千多年前想出来的类比竟然与两千多年后的科学家们的解刨结果相当一致，你对比一下就知道了："),e("p",null,"大脑结构 形象称呼 柏拉图的双轮战车类比 大脑皮层 人类大脑 车夫 内皮层 猴子大脑 白马 脑干 鳄鱼大脑 黑马 相对于 “人类、猴子、鳄鱼” 的说法，我更喜欢柏拉图的战车比喻 —— 因为车夫、白马、黑马、战车是一个能够统一的组合。我们的身体就好像是那辆战车，我们脑子里住着三个自我，一位车夫，一匹白马，和另外一匹黑马。他们三个不应该是相互的敌人，也不应该是相互的仇人，他们之间的关系最好是，也只能是，合作关系。他们三个之间相互合作的越紧密，那战车就越有效率；否则的话，战车就毫无用处。")],-1),e("p",null,"对我的启发是借助不同的类比对一个概念及其关系的逐层递进的思考方式。",-1),e("p",null,"通过人类大脑、猴子大脑和鳄鱼大脑的类比，我们能清楚知道大脑平层，内皮层和脑干所负责的不同功能。但这不能指导我们的行动，也就是概念还不够清晰，而通过车夫，白马和黑马，我们能清晰的知道大脑平层，内皮层和脑干的关系，建立了大脑工作机制的基础了解。从而形成遇事时的正确处理方法——不管什么事情，都需要三个角色分别处理一次，而后交由车夫决定，至于车么，就是你的身体，先别动 —— 5 分钟之后再行动。",-1),e("p",null,"暂时还没想清楚还可以用在哪里。",-1)])])}const _=o(a,[["render",n]]);export{m as __pageData,_ as default};
